#!/usr/bin/env bash
# Auto-generated by make_jobs.sh: model=mistral (mistral-medium-latest), env=crafter
set -uo pipefail
HERE="$(cd "$(dirname "$0")/.." && pwd)"
source "$HERE/config.sh"
[[ -f "$KEYS_FILE" ]] && source "$KEYS_FILE"
if [[ -n "$CONDA_ENV" ]]; then
  source "$(conda info --base)/etc/profile.d/conda.sh" && conda activate "$CONDA_ENV"
fi
export OPENAI_API_KEY="${MISTRAL_API_KEY:?MISTRAL_API_KEY not set in $KEYS_FILE}"
cd "$BALROG_DIR"
OUT="$RESULTS_DIR/mistral/crafter"
mkdir -p "$OUT"
echo "[$(date '+%F %T')] START mistral/crafter"
python eval.py \
  agent.type=$AGENT_TYPE $AGENT_ARGS \
  envs.names=crafter \
  client.client_name=nvidia client.model_id=mistral-medium-latest client.base_url=https://api.mistral.ai/v1 \
  eval.num_workers=2 eval.output_dir="$OUT" \
  eval.num_episodes.crafter=1 eval.max_steps_per_episode=300 client.max_retries=8 client.delay=4
rc=$?
echo "[$(date '+%F %T')] END mistral/crafter (exit $rc)"
exit $rc
